CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261105173103_InitialMigration') THEN
    CREATE TABLE "Importados" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Codigo" text NOT NULL,
        "Cedula" text NOT NULL,
        "Nombre" text NOT NULL,
        "Direccion" text NOT NULL,
        "Matricula" text NOT NULL,
        "AreaTerreno" integer NOT NULL,
        "AreaConstruida" integer NOT NULL,
        "Tipo" integer NOT NULL,
        "Estado" integer NOT NULL,
        "EsMunicipio" boolean NOT NULL,
        "Exento" boolean NOT NULL,
        "Avaluo" double precision NOT NULL,
        "Estrato" text NOT NULL,
        "Desenglobo" boolean NOT NULL,
        "Zona" text NOT NULL,
        CONSTRAINT "PK_Importados" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261105173103_InitialMigration') THEN
    CREATE TABLE "Parametros" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nit" text NOT NULL,
        "Direccion" text NOT NULL,
        "Telefono" text NOT NULL,
        "Divipo" text NOT NULL,
        "Ciudad" text NOT NULL,
        "Nombre" text NOT NULL,
        "FechaInicioInteres" date NOT NULL,
        "ValorRecibo" double precision NOT NULL,
        "Correo" text NOT NULL,
        "FechaNuevaLey" date NOT NULL,
        "FinNuevaLey" date NOT NULL,
        "CobraAdicional" boolean NOT NULL,
        "CoactivoManual" boolean NOT NULL,
        "DiasPersuasivo" integer NOT NULL,
        "DiasCoactivo" integer NOT NULL,
        "DiasMandamiento" integer NOT NULL,
        CONSTRAINT "PK_Parametros" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261105173103_InitialMigration') THEN
    CREATE TABLE "Procesos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "TipoProceso" integer NOT NULL,
        "Codigo" text,
        "Comparendo" text,
        "Cedula" text,
        "Nombres" text,
        "Infraccion" text,
        "Direccion" text,
        "Telefono" text,
        "Ciudad" text,
        "Departamento" text,
        "Fecha" date,
        "FechaVencimiento" date,
        "FechaSancion" date,
        "FechaMandamiento" date,
        "FechaProceso" date,
        "Estado" integer,
        "NombreEstado" text,
        "Desde" date,
        "Hasta" date,
        "SemestreUno" integer,
        "SemestreDos" integer,
        "Valor" double precision NOT NULL,
        "Resolucion" text,
        "Expediente" text,
        CONSTRAINT "PK_Procesos" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

