        "Direccion" text,
        "Matricula" text,
        "AreaTerreno" integer NOT NULL,
        "AreaConstruida" integer NOT NULL,
        "Tipo" integer,
        "NombreTipo" text,
        "Estado" integer NOT NULL,
        "EsMunicipio" boolean NOT NULL,
        "Exento" boolean NOT NULL,
        "Avaluo" double precision NOT NULL,
        "TipoId" integer NOT NULL,
        "Estrato" text,
        "Desenglobo" boolean NOT NULL,
        "Zona" text,
        "Barrio" integer NOT NULL,
        "Ley550" boolean NOT NULL,
        "PropietarioId" integer NOT NULL,
        CONSTRAINT "PK_Maestro" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Maestro_Propietarios_PropietarioId" FOREIGN KEY ("PropietarioId") REFERENCES "Propietarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

